// The coercion audit, live: same "5", three different stored types.
const sides    = nb.get('sides');       // numeric select   → number
const sidesStr = nb.get('sides_str');   // valueType:string → string
const shape    = nb.get('shape');       // string options   → string
const level    = nb.get('level');       // numeric radio    → number
const align    = nb.get('align');       // string radio     → string
const wireframe = nb.get('wireframe');  // checkbox         → boolean

console.log('sides', sides, '(' + typeof sides + ')  ×2 =', sides * 2);
console.log('sides_str', sidesStr, '(' + typeof sidesStr + ')  ×2 =', sidesStr * 2, '← string coerces in arithmetic, but it IS a string');

return {
  sides:     { value: sides,     type: typeof sides },      // number
  sides_str: { value: sidesStr,  type: typeof sidesStr },   // string
  shape:     { value: shape,     type: typeof shape },      // string
  level:     { value: level,     type: typeof level },      // number
  align:     { value: align,     type: typeof align },      // string
  wireframe: { value: wireframe, type: typeof wireframe },  // boolean
};

// Gotcha check — this is the regression the overhaul fixed. If a numeric
// select ever binds a string again, this cell goes red.
const sides = nb.get('sides');
const level = nb.get('level');
const wireframe = nb.get('wireframe');

const ok =
  typeof sides === 'number' &&
  typeof level === 'number' &&
  typeof nb.get('sides_str') === 'string' &&   // override honoured
  typeof wireframe === 'boolean';

if (!ok) throw new Error('coercion regressed: ' +
  JSON.stringify({ sides: typeof sides, level: typeof level }));
return 'numeric selects/radios bind numbers, valueType override honoured, checkbox is boolean ✓';
